SELECT medicare2_2.hcpcs_description AS hcpcs_description,   medicare2_2.nppes_entity_code AS nppes_entity_code,   medicare2_2.provider_type AS provider_type FROM medicare2_2 WHERE ((medicare2_2.nppes_provider_state = 'NY') AND (medicare2_2.nppes_provider_country = 'US')) GROUP BY medicare2_2.hcpcs_description,   medicare2_2.nppes_entity_code, medicare2_2.provider_type;
